/* ==========================================================================
   2026-08 選択肢の区間の境界を修正（wtemp / heattime）
   --------------------------------------------------------------------------
   spec.js の選択肢ラベルが

     wtemp    u10 '10℃未満' / t1015 '10〜15℃' / t1518 '15〜18℃' /
              t1822 '18〜22℃' / o22 '22℃以上'
     heattime u30 '30分未満' / m30 '30〜60分' / m60 '60〜90分' / o90 '90分以上'

   となっており、**15・18・60・90 がどちらの区分にも属してしまっていた。**

   これは机上の問題ではなく実際に不整合を生んでいた。水風呂15℃の施設が
     id=45  HARUKA KANATA 森のヴィラ      t1518
     id=262 Earthboat Minakami Hodaigi  t1015
   と別々の区分で記録されていた。

   ラベルを「下限を含み上限を含まない」に書き換えて解消した。

     wtemp    '10℃以上15℃未満' / '15℃以上18℃未満' / '18℃以上22℃未満'
     heattime '30分以上60分未満' / '60分以上90分未満'

   キー名は変えていないので既存データの移行は不要。値の見直しは1件のみ。

     id=262 water_temp t1015 -> t1518（出典「15度の水風呂」）

   境界が決まったことで、これまで「どちらの区分か決められない」として
   見送っていた3件を記録できた。

     id=49  成田さくら邸（共用サウナ かぐやの森）  15度 -> t1518
     id=282 GLAMPING KASHIMA 753             15度 -> t1518
     id=254 伊豆グランヴィレッジ グランピング        18度 -> t1822

   water_temp は 6件 -> 9件。CLAUDE.md の「値の書き方の規約」にも追記した。

   heat_time は記録が0件だったため移行の影響なし。
   ========================================================================== */

