/* ==========================================================================
   2026-09 winter_access をチャネルAとして導出（230件）
   --------------------------------------------------------------------------
   設計書はこの項目をチャネルAに置き「標高＋緯度＋県の道路規制情報から判定。
   標高700m超＋日本海側は自動で『推奨』に倒す」としていたが、実装されないまま
   ch: 'owner' に分類され3件しか入っていなかった。標高は286件すべて揃っている
   ので回収した。tools/winter.py を追加し、spec.js の ch も auto に直した。

   ■ **200〜500m の帯は意図的に空けた**
     最初は「500m以上=tire / 200〜500m=snow / 200m未満の沿岸=ok」で組んだが、
     ドライランで既存の手作業3件と食い違った。3件はいずれも 200〜500m 帯で、
     **すべて tire。標高だけの判定なら snow になるところを人間は tire と
     書いていた。**

       id=204 オーシャンビュー南熱海 290m / id=124 ドワーフの村 428m /
       id=210 熱海オーシャンハウス 439m

     この帯には伊豆高原（約250m）から那須（約450m）まで実態の異なる地域が
     混在する。**推定が人間の判断より甘い側に出るなら、その帯は埋めるべき
     ではない。** 54件を未調査のまま残した。

   ■ 閾値を設計書の700mではなく500mにした
     箱根仙石原（約650m）のように700m未満でも冬タイヤが要る地域が含まれる。
     **過剰に警告する誤りは無害だが、警告し損ねる誤りは危険**という非対称性。

   ■ `closed`（冬季通行止めあり）は自動では付けない
     実際の道路規制データが要る。机上調査かオーナー回答に委ねる。

   ■ 県と標高の分布（判定の根拠）
     千葉73件・茨城13件は全件が標高200m未満（最大105m/127m）で ok に倒せる。
     山梨41件は最低249m・中央値871m、長野27件は中央値943m、群馬12件は
     最低483mで、いずれも tire 側。神奈川41件だけが二極化しており、
     湘南・三浦の海沿い14件が200m未満、箱根14件が700〜1000m。

   結果: ok 122 / tire 111 / 未調査 53。closed は0件。
   ========================================================================== */

