/* ==========================================================================
   2026-09 スキーマ改修2件 … kitchen_type に cassette、coldbath_season を新設
   --------------------------------------------------------------------------
   設計書はステップ1（項目と選択肢の確定）を「後戻り不可」としているが、
   **オーナー調査票の送付前なので、いま直すのが正しいタイミング。**
   早期に early_late を分割したのと同じ理由で、調査で繰り返し出てきた
   取りこぼしを2件まとめて解消した。

   ■ `kitchen_type` に `cassette`（カセットコンロのみ）
     備え付けのコンロが無くカセットコンロだけの施設が4件あり、判断が
     割れていた。id=211 / id=24 / id=266 では「卓上の携帯コンロは備え付け
     キッチンの種別ではない」として採用を見送る一方、id=95 には既存値
     `gas` が入っており不整合だった。

     `gas` と書くと「ガスコンロあり」で絞り込んだ利用者が卓上の携帯コンロ
     だけの施設に当たってしまうため、選択肢を分けることにした。

       id=95  「室内にガスボンベ式のカセットガスコンロを用意」→ gas から cassette へ訂正
       id=211 調理器具リストに「カセットコンロ」            → cassette
       id=24  設備リストに「カセットコンロ」                → cassette
       id=266 「カセットコンロのレンタル」                  → **入れない**（備え付けではない）

   ■ `coldbath_season`（通年利用可 / 冬季休止）
     冬季に水風呂が凍結・休止する施設が調査のたびに出てきたが、記録する
     場所が無かった。サウナ目的の利用者には決定的な情報。

       「※冬季は凍結防止のため屋外の水風呂、シャワー、水栓の使用を休止させて
         頂きます。サウナから内風呂にすぐアクセスできますので、内風呂を
         水風呂代わりにご利用ください。」（id=103 Private villa FujiNagi）
       「冬季（11月～3月末）は水道凍結の恐れがあるため、水風呂のご利用は
         停止しております。」（id=198 T&A）
       「（※冬季は凍結のため利用不可）」（id=190 Hygge chalet hakuba）

     SANU の MOSS型5拠点（北軽井沢2nd／八ヶ岳3rd／白馬1st／河口湖2nd／
     南アルプス1st）は公式マガジンが名指しで対象拠点を列挙したうえで
     「テラスの水風呂は冬季11〜4月は凍結防止のため利用制限」と書いている。
     計8件に `winter` を記録した。

     **LEVATA の「12〜3月は露天サウナ使用不可」はサウナ本体の制限なので
     この項目には当てはまらない。** 季節制限の事例5件のうち4件が水風呂に
     集中していたので、水風呂に限った項目にした。

   desk項目は10から11になった。
   ========================================================================== */

