/* ==========================================================================
   2026-09 交差検証で「型番による熱源判定」が逆だったと判明（id=101）
   --------------------------------------------------------------------------
   V14-1 のエージェントが id=101 KURA YARD の stove=electric を
   「型番が明記されているので確定できる」として一致と報告してきたが、
   **Harvia の Legend シリーズは薪式**だった。

     公式（kurayard.com/sauna）:
       「サウナストーブは、本場フィンランドのサウナメーカーHarviaの
         『LEGEND15』を採用」
       ※熱源の明記も「薪」の語も一切ない

     Harvia の製品情報:
       harvia.jp は LEGEND150 を型番 **WK150LD** で掲載（WK は薪式）
       「Harvia Legend 150 **Wood Burning** Sauna Stove」（海外販売店）
       「サウナ**薪ストーブ** HARVIA LEGEND 150」（国内販売店）

   **エージェントが「電気ストーブ 13.8kW」と読んだ idetox.jp は、実際には
   「Harvia LEGEND150｜16kW相当｜サウナストーブ｜薪ストーブ」と載せている。**
   代理店サイトの表記を読み違えたまま、型番という強い根拠の形で報告してきた。

   ■ **stove=electric を削除したが、wood にも書き換えなかった**
     公式の表記が「LEGEND15」で Harvia の型番「LEGEND150」と完全には一致せず、
     しかも公式ページに薪の扱い（薪割り・薪をくべる・薪代）への言及が一度も無い。
     薪サウナなら通常は利用者向けの案内が要るはずで、型番の読み替えだけで
     断定するのは危うい。**マイグレ15施設と同じく未調査に戻す。**

   ■ 規約そのものは否定されない
     id=111 の「HARVIAのCILINDROを採用しています」→ electric は正しい
     （Cilindro は電気専用で薪式のラインナップが無い）。
     **「型番なら確定できる」は有効だが、型番を実際にメーカーの製品情報に
     当たって確かめること、代理店の表記を鵜呑みにしないことが要る。**
     CLAUDE.md にこの2例を並べて記載した。

   ■ この検証は自分（Opus）で行った
     Sonnet 側のレート制限で交差検証エージェントが3度落ちたため。
     **自分が CLAUDE.md に書いた規約の妥当性検証は設計の範囲**と判断した。
   ========================================================================== */

/* ==========================================================================
   2026-09 fix_villa.py に remove_ota を追加（OTAリンク修復の準備）
   --------------------------------------------------------------------------
   壊れた ota リンクの方針が「差し替えを試み、見つからなければ消す」に
   決まったが、**削除する操作が無かった。** set_villa は値の置換しかできず、
   ota は VILLAS の中の入れ子オブジェクトなのでキーごと落とせない。

     "ota": {"booking": "...", "ikyu": "...", "rakuten": "..."}

   remove_ota を追加した。前後どちらかのカンマごと落とし、最後の1件なら
   ota 自体を空にする。動作確認として id=60 and FOREST勝浦 竹の離れ の
   airbnb キーを削除した（値は `airbnb.jp/s/homes` という汎用検索URLで、
   施設固有のページではなかった）。施設数286・JSONの構文とも維持を確認。

   壊れているエントリは全走査で38件（31施設）。類型は4つ。

     広告中継URL（google.com/aclk）      14件
     別施設と共有                        6組
     キーとドメイン不一致                7件
     検索結果ページ                      4件

   正しいURLの探索はエージェントに委譲した。
   ========================================================================== */

/* ==========================================================================
   2026-09 交差検証 … 「最大を採る」は数値項目にだけ使える（id=113）
   --------------------------------------------------------------------------
   V14-1 のエージェントが id=113 ASH Villa の coldbath を bath から tub へ
   訂正するよう提案してきたので交差検証に回したところ、**提案の引用は正確
   だったが、見落としが2つあった。**

   ■ 棟別に確認した結果
     Deluxe Villa 1010（最大10名）
       「お風呂は大きなヒノキ風呂、周りを気にせずご家族ご一緒に入って
         お楽しみ頂けます。**サウナのあとの水風呂にもご利用いただけます。**」
       → 名詞が浴槽なので tub 相当。
       さらにFAQ「プールをご用意しているのはDeluxe villaのみ…**ご使用頂けない
       季節は水景や水風呂としてご利用くださいませ。**」で pool 相当の
       副次的な根拠もある（同じ棟に水風呂になりうる設備が2つある）。

     2-Bedroom Villa 2020（最大6名）
       **水風呂の言及が一切ない。** 風呂は「松山油脂のこだわりのアロマと
       バスソルト…贅沢なバスタイムをお楽しみくださいませ。」とアロマ入浴の
       演出のみで、サウナとの接続が書かれていない。設備アイコンも
       1010が「プール／サウナ」の2つに対し2020は「サウナ」のみ。

   ■ **既存の bath はどちらの棟の記述にも直接の裏付けが無かった**ので削除した。
     1010 だけなら tub が最も支持されるが、2020 は不明。
     棟で異なる項目は入れないという方針に従う。

   ■ **ここで規約が1つ明確になった**
     エージェントの指摘が的確だった。

       「capacity で1010の数値（10）を代表値に採用した先例があるが、これは
         『施設全体の最大』という数値集約の文脈で正当化されたものであり、
         coldbath のようなカテゴリ値に同じ理屈を機械的に適用してよいかは
         別問題」

     **「最大を採る」は数値項目にだけ使える。** `capacity` で棟別の最大を
     採るのは「施設全体で最大N名が泊まれる」という集約に意味があるからで、
     `coldbath` や `sauna_type` のような選択肢型には「最大」に当たるものが無い。
     棟で違えば入れない（id=113 の coldbath、id=38 と id=130 の sauna_type は
     いずれもこれで削除した）。CLAUDE.md に追記した。
   ========================================================================== */

/* ==========================================================================
   2026-09 ota リンクの全面修復（38エントリ / 31施設）
   --------------------------------------------------------------------------
   2026-08 の全件走査で見つけていた壊れた ota リンクを、方針「差し替えを試み、
   見つからなければ消す」に従って処理した。実機ブラウザで開いて住所を照合し、
   一致したものだけ差し替えている。

   ■ 差し替え 14件 / 削除 10件（残り14件は共有元が正しく変更不要だった）

   ■ **「別施設と共有」型はすべて『片方が正しく、もう片方が誤っていた』**
     両方消すのではなく、誤った側だけ直せばよかった。

       id=77/78  booking と rakuten … gran-tocoro / HOTEL/191908 は id=78 のもの。
                 id=77 の正しい booking は tocoro-mt-fuji-kisaragi
                 （「enico MtFuji smile」船津3130-3 でDBと一致）
       id=86/88  booking … norm-air-fuji は id=86 のもの。id=88 は norm-fuji
                 （公式 hotel-norm.com の「長浜2109-1」がDBと一致）
       id=201/203 ikyu … 00051776 は id=203 のもの。id=201 は同ブランド姉妹施設
                 2件の「グループ施設一覧」にも公式にも一休への言及が無く、
                 掲載が無いと判断して削除
       id=204/205 agoda … atamishizenkyo は id=205 のもの
       id=245/246 ikyu … 00052094 は id=245 のもの。id=246 は 00052264

   ■ **id=246 は ota が3つとも壊れていた。** ikyu と agoda の両方に id=245 の
     URL が入り、agoda はキーとドメインの不一致も兼ね、airbnb キーには
     Expedia の URL が入っていた。

   ■ **Airbnb 5件は保留した**（id=14 / 118 / 126 / 227 / 228）。
     Airbnb が自動ブラウザを拒否し（どのURLでも検索トップにリダイレクト、
     Wayback にもキャッシュ無し）、住所の実機照合ができなかった。
     検索索引のページタイトル一致だけでは「独立した2回以上の検索で一致した値
     だけ採る」を満たさない。同じ調査中に **id=204 で「COCO VILLA MINAMIATAMI」
     という地名だけ同じ別ブランド施設が Agoda 検索に紛れ込んでおり**
     （住所は伊東市網代でDBの熱海市下多賀と不一致）、リスクは現実のもの。

   ■ **副次的な発見: 自動判定の誤検知が1件あった。**
     id=26 の rakuten は vacation-stay.jp で「ドメイン不一致」と分類していたが、
     実際は楽天LIFULL STAY の自社ブランド（Vacation STAY / Rakuten Oyado）で
     内容も正しかった。ドメイン名だけで判定すると誤る。

   ==========================================================================
   2026-09 fix_villa.py の URL 置換が個別ページを壊すところだった
   --------------------------------------------------------------------------
   上を適用する前の --dry-run で「agoda を 2 箇所差し替え」という出力が出た。
   villas/*.html 側の置換が旧い値の単純な文字列置換で、コメントに
   「個別ページは1施設分なので誤爆しない」と書かれていたが、**URL では誤爆する。**

     (a) 前方一致 … id=113 の agoda 値 "https://ash-villa.com/" は、同じページの
         公式リンク "https://ash-villa.com/?utm_source=GBP&..." の前方一致。
         **公式サイトのリンクが Agoda の URL に書き換わるところだった。**
     (b) 同一URL … id=246 は ikyu と agoda が両方 "00052094" で、先に処理した
         ikyu の置換が agoda のぶんも巻き込み、agoda は自分の旧値を見失う。

   ota のリンクはボタンのラベル（「一休.com」「Agoda」など）で対象を特定する
   ように直した。公式など他の項目は閉じ引用符まで含めて一致させる。
   あわせて **remove_ota が villas/*.html に対応していなかった**ことも分かり、
   index.html から消したキーのボタンが個別ページに残っていた。走査したところ
   4件あり（id=170/255/281 の楽天が検索結果ページ、id=60 の Airbnb が検索URL）、
   **利用者には壊れたリンクが見えたままだった。**

   同じ取り残しが再発しないよう、validate.py に index.html の ota キーと
   個別ページのボタンの一致を見る検査を足した。
   ========================================================================== */

