/* ==========================================================================
   2026-09 交差検証 … id=239 のフィールド混線、id=248 / id=283 の定員
   --------------------------------------------------------------------------
   ■ **id=239 AMAO VILLA — 5施設の間でフィールドが混線していた**

     当初は「一休のアクセスが富戸911-122でDBの富戸1007-32と違う」ことから
     **同名の別施設**（OYADO S 型）を疑ったが、そうではなかった。公式FAQで
     AMAO VILLA は熱海／伊豆高原／城ヶ崎／富戸／自然郷の5施設で、富戸は1つだけ。

       addr    … 富戸1007-32 は **AMAO VILLA 伊豆高原** の住所
       feature … 「2024年に開業したばかりの**AMAO VILLA 城ヶ崎**は…」＝城ヶ崎の紹介文
       desc    … 「**熱海**の雄大な景色を…**熱海海上花火**を一年中楽しめます」＝熱海の紹介文
       official / ota.ikyu … どちらも富戸で正しい
       capacity=9 / sauna_cap=8 / sauna_temp=95 … 富戸公式の記載と一致

     addr を訂正し、pet_ok を yes から no に訂正した。否定は独立した3出典で一致。

       一休 基本情報「ペット　不可」／設備・特徴「× ペット可」
       公式から直接リンクする予約システム beds24「**ペット：不可**」
       公式FAQ の見出し「**AMAO VILLA 富戸 (※犬との宿泊は不可)**」

     同じ beds24 の基本情報が「**BBQ：なし**」なので bbq タグも外した。
     **feature と desc は姉妹施設の文章のままで、利用者に見える誤りとして残る。**

   ■ **住所監査の限界が分かった。座標も一緒に間違っていた。**

     CLAUDE.md には「addr が壊れていても座標は正しい」と書いてあり、これは
     2026-09 の全件監査で確かめた事実だった。**ただしそれは addr が『壊れている』
     場合の話だった。** id=239 の addr は壊れていない。**実在する、姉妹施設の
     正しい住所**だった。Google Places の searchText は施設名＋住所で引くので、
     この場合は素直に姉妹施設の座標を返す。

       data/coordinates.json の id=239        (34.901694, 139.123776)
       旧 addr「富戸1007-32」をGSIで引いた点  (34.901443, 139.122162) … 0.15km
       正しい「富戸911-122」をGSIで引いた点   (34.887718, 139.121674) … 1.57km

     **保存座標は旧 addr と 0.15km で一致している。** つまり
     「addr をジオコーディングして座標と比べる」という監査手法では**この型は
     絶対に検出できない**（両方が同じ誤りを共有しているため）。
     今回の検出の糸口は OTA ページの住所との食い違いだった。

     **id=239 のチャネルA（標高・スーパー・コンビニ・IC・駅・温泉）は
     AMAO VILLA 伊豆高原のものになっている。** 座標の取り直しと channel_a.py の
     再実行が要る（GMAPS_KEY が必要なため今回は実施していない）。

   ■ **id=248 エンゼルフォレスト中伊豆 — capacity 4 → 6**

     公式の予約システムで棟一覧を確認したところ棟種別は2つだけ。

       「【プライベートドッグラン付き】新築貸別荘コテージ1LDK（洋室1部）・**4名定員**）」
         …露天風呂付でサウナの記載なし
       「【プライベートドッグラン＆サウナ付き】新築貸別荘コテージ2LDK（洋室2部）・**6名定員**）」

     既存の4はサウナの無いスタンダード棟の数字だった（DBの sauna_exists は room で、
     サウナがあるのは6名タイプのみという実態と整合する）。FAQ「1部屋に最大何人まで
     宿泊できますか？」の回答は「貸別荘やコテージにより定員は異なります。」で
     施設全体の数字を出していない。棟別の最大を採る規約に従い 6 とした。

   ■ **id=283 林音 — capacity 4 → 7。ただし規約の限界が見えた**

       「部屋名　**クラブメゾネットコテージ**　面積　86.12㎡　定員　**2〜7名**」

     グランピング4種＋コテージ7種の計11タイプで、定員は「2〜4名」が中心だが最大は7。
     FAQ 全55問を確認したが施設全体の最大人数は出ていない。

     **id=113 / 150 / 191 は同一ヴィラの棟違いだったが、林音は11タイプあり、
     グランピングテントと2階建てコテージという性質の違う商品群が混在する。**
     「施設として最大7名まで泊まれる」は正しいが、テントを取った利用者には
     当てはまらない。1エントリ＝1施設という構造の限界がここにも出ている。

     あわせて validate.py の交差チェックを直した。**sauna_exists=shared の施設では
     サウナ定員と施設定員を比べても意味がない。** 林音は共用の「収容人数30人の
     大型のサウナ室」を持つため sauna_cap=30 > capacity=7 で警告が出ていた。
   ========================================================================== */

/* ==========================================================================
   2026-09 空欄埋めの波 V14-5 … 12施設
   --------------------------------------------------------------------------
   これまでの波は「出典なしの値を検証する」ことが主目的だったが、出典なしの残りが
   薄くなったので空欄埋めに切り替えた。17項目を新たに記録した。

   ■ **`kitchen_type` に初めて否定値が入った（id=105 BLANC FUJI）**

     `coldbath` `kitchen_type` `loyly` `outdoor_rest` `rest_chair` `wifi` の6項目は
     「なし」を一度も記録していなかった。公式サイトは「ある物」は宣伝するが
     「無い物」は書かないため。**id=105 で kitchen_type=none を記録できた。**

       一休 設備・特徴「**× キッチンあり**」
       公式FAQ「施設内で調理やバーベキューはできますか？」→「Living Villa に
         ご宿泊の場合のみ、客室ウッドデッキの…BBQプランをお申し込みいただけます。
         **機材や食材はすべてホテルからご提供させていただき**、お客様ご自身で
         グリルしてお召し上がりいただくスタイルになります。」

     **○✕欄の否定と、FAQ の「調理設備は無く機材貸与制」という説明が噛み合っている。**
     一休の○✕欄はスコープが項目と一致する構造化データなので、こういう使い方ができる。

   ■ **`stove` に新しい根拠の型が出た（id=47 Hackberry Holiday Home）**

     これまで採用できたのは「サウナ自体を修飾する熱源の記述」か「メーカー公式で
     裏の取れた型番」だけだった。今回は**運用の記述**から決めた。

       FAQ「サウナの操作はどのようにしますか？」
         →「お客様による**スイッチの操作**が必要です。詳しくは室内の
            インフォメーションブックをご覧ください。」

     **薪なら「薪をくべる」「着火する」になる操作が、スイッチ操作と書かれている。**
     設備紹介の「フィンランド製のサウナストーブを設置しています。」だけでは
     メーカー名すら無く確定できないが、この運用記述と合わせて electric とした。

   ■ **`cassette` の適用条件がはっきりした（id=17 と id=23 の対比）**

     id=23 The TRAVELERS Chateau … キッチン設備一覧の火口が「カッセットコンロ」だけで
     備え付けのコンロが無い → **cassette**
     id=17 the MELLOW HOUSE … 「カセットコンロ、**３口コンロ**」と併記されており、
     備え付けのコンロがある。しかしその３口の熱源（IH/ガス）が書かれていない
     → **cassette でもなく ih/gas でもないので入れない**

     **cassette は「備え付けが無い」ことが条件。** 併記されていたら使えない。

   ■ **`sauna_type` のスキーマ不足に実例が3件増えた**

       「サウナは、**ミストサウナ**となっております。ご注意ください。」（id=26）
       「関東初導入の最新式**ドライスチームサウナ**」（id=44）
       サウナイキタイ「ドライサウナ　**遠赤外線型**」（id=63）

     いずれも indoor / hut / barrel / tent のどれにも当たらない。
     `stove` も同様で、ミストや遠赤外線は薪/電気/ガスという区分と性質が違う。

   ■ **出典URLの劣化が desk 側にも起きている（id=169）**

     id=169 の pet_ok と wifi は `https://www.fvrentals.com/` を出典に持つが、
     **これはドメインルートで施設ページを特定できないうえ、いまアクセスすると
     汎用トップページにリダイレクトされる。** ota リンクで見つけた劣化と同種。

     全走査したところ**ドメインルートを出典にしているセルは383件**あるが、
     その大半は施設自身の公式サイトのルートで正当（1施設1サイトなので特定できる）。
     **公式と違うドメインルートは12件**で、多くは www の有無などの表記ゆれ。
     そのなかに `https://newsite.kitakaruizawafarmstay.com/`（id=199）があり、
     **`newsite.` はステージング環境の疑いがある。**

   ■ **WebSearch の要約が実在しない記述を出した（id=66 Villa Yno）**

     AI要約に「HEARVIA(Harvia)製サウナストーブ」とあったが、HAMONI・一休・
     Yahoo!トラベルのどのページを開いても該当の記述が見つからなかった。
     **実ページで確認する手順が働いた例。** クチコミの「サウナの電源探しに苦労したり」は
     電気式を示唆するが公式記載ではないため見送った。

   ■ **id=2 るうふ 波之家 — 公式優先が効いている例**

     公式「テントサウナにつきまして、2026年1月16日をもってご利用を終了いたしました。」
     に対し、一休は「サウナ / 貸切風呂」「サウナ：あり」のまま更新されていない。
     クチコミも廃止前の体験談。既存の sauna_exists=no は正しく、変更不要。

   ■ **採用を見送ったもの**

     - id=169 / id=63 の capacity … 根拠が OTA の定員欄しか無い
       （Booking の部屋タイプ「× 8」、一休「定員 1名～3名」）。値はそのまま。
     - id=47 の sauna_type … 「サウナ室横にある虫とり網をご利用ください。」が
       プールの注意事項に出てくる。**「サウナ室」はサウナ小屋の内部にも使う語**で、
       しかもプールの隣という位置は屋外構造を示唆する。indoor と断定できない。
     - id=63 の water_temp … サウナイキタイの構造化データは「18 度」だが
       訪問記は「水温表示は17.9℃」。**区間の境界がちょうど18℃**（18ちょうどは t1822、
       17.9 は t1518）なので、どちらの区分にも倒せない。
     - id=63 の outdoor_rest … 訪問記2件が独立に「ととのい椅子がひとつも無い」
       「椅子はない」と述べているが、投稿ベースなので否定の根拠にしない。
   ==========================================================================
   ========================================================================== */

